=== FILE: apb_regs.v ===
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements interface_spec.md per microarchitecture.md (zero wait states,
// no state machine, PSLVERR for unmapped addresses, synchronous active-low reset).
`default_nettype none

module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                      pclk,
    input  wire                      presetn,
    input  wire [ADDR_WIDTH-1:0]     paddr,
    input  wire                      psel,
    input  wire                      penable,
    input  wire                      pwrite,
    input  wire [DATA_WIDTH-1:0]     pwdata,
    input  wire [DATA_WIDTH/8-1:0]   pstrb,
    output reg  [DATA_WIDTH-1:0]     prdata,
    output wire                      pready,
    output wire                      pslverr
);

    localparam integer STRB_WIDTH = DATA_WIDTH / 8;

    // ------------------------------------------------------------------
    // Transfer qualification and address decode
    // ------------------------------------------------------------------
    // The access phase is the one cycle in which the response is sampled
    // and a write takes effect (pready is always high).
    wire       access = psel && penable;

    // Mapped: word aligned and inside 0x0..0xC.
    wire       mapped = (paddr[1:0] == 2'b00) &&
                        (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire [1:0] idx    = paddr[3:2];

    wire       wr_en  = access &&  pwrite && mapped;
    wire       rd_en  = access && !pwrite && mapped;

    wire       we0    = wr_en && (idx == 2'd0);
    wire       we1    = wr_en && (idx == 2'd1);
    wire       we2    = wr_en && (idx == 2'd2);
    wire       we3    = wr_en && (idx == 2'd3);

    // Byte-lane write mask: lane n enabled by pstrb[n].
    wire [DATA_WIDTH-1:0] wmask;

    genvar gb;
    generate
        for (gb = 0; gb < STRB_WIDTH; gb = gb + 1) begin : g_wmask
            assign wmask[8*gb +: 8] = {8{pstrb[gb]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Register file: four separate flops, synchronous active-low reset
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (we0) reg0 <= (reg0 & ~wmask) | (pwdata & wmask);
            if (we1) reg1 <= (reg1 & ~wmask) | (pwdata & wmask);
            if (we2) reg2 <= (reg2 & ~wmask) | (pwdata & wmask);
            if (we3) reg3 <= (reg3 & ~wmask) | (pwdata & wmask);
        end
    end

    // ------------------------------------------------------------------
    // Read data: combinational mux, zero unless a mapped read access
    // ------------------------------------------------------------------
    always @(*) begin
        prdata = {DATA_WIDTH{1'b0}};
        if (rd_en) begin
            case (idx)
                2'd0:    prdata = reg0;
                2'd1:    prdata = reg1;
                2'd2:    prdata = reg2;
                2'd3:    prdata = reg3;
                default: prdata = {DATA_WIDTH{1'b0}};
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Response
    // ------------------------------------------------------------------
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    // ==================================================================
    // Formal properties (default parameters only). The decode and the
    // byte merge below are written independently of the design's own.
    // ==================================================================
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk)
        f_past_valid <= 1'b1;

    // ---------------- Manager (requester) assumptions ----------------
    always @(*) begin
        if (!f_past_valid)
            assume(!presetn);
        if (!presetn)
            assume(!psel);
        if (penable)
            assume(psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid && penable) begin
            // Access only straight after a setup phase, outside reset.
            assume($past(presetn));
            assume($past(psel) && !$past(penable));
            // Request stable from setup through access.
            assume(paddr  == $past(paddr));
            assume(pwrite == $past(pwrite));
            assume(pwdata == $past(pwdata));
            assume(pstrb  == $past(pstrb));
        end
        // A setup phase is always followed by its access phase.
        if (f_past_valid && $past(presetn) && $past(psel) && !$past(penable))
            assume(psel && penable);
    end

    // ---------------- Independent reference decode ----------------
    wire f_access = psel && penable;
    wire f_mapped = (paddr == 8'h00) || (paddr == 8'h04) ||
                    (paddr == 8'h08) || (paddr == 8'h0C);
    wire f_wr0    = f_access && pwrite && (paddr == 8'h00);
    wire f_wr1    = f_access && pwrite && (paddr == 8'h04);
    wire f_wr2    = f_access && pwrite && (paddr == 8'h08);
    wire f_wr3    = f_access && pwrite && (paddr == 8'h0C);

    reg [DATA_WIDTH-1:0] f_rdata;
    always @(*) begin
        case (paddr)
            8'h00:   f_rdata = reg0;
            8'h04:   f_rdata = reg1;
            8'h08:   f_rdata = reg2;
            8'h0C:   f_rdata = reg3;
            default: f_rdata = {DATA_WIDTH{1'b0}};
        endcase
    end

    // ---------------- Response assertions ----------------
    always @(*) begin
        assert(pready);
        if (!f_access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(!pslverr);
        end else begin
            assert(pslverr == !f_mapped);
            if (pwrite)
                assert(prdata == {DATA_WIDTH{1'b0}});
            else
                assert(prdata == f_rdata);
        end
    end

    // ---------------- Register assertions ----------------
    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert(reg0 == {DATA_WIDTH{1'b0}});
            assert(reg1 == {DATA_WIDTH{1'b0}});
            assert(reg2 == {DATA_WIDTH{1'b0}});
            assert(reg3 == {DATA_WIDTH{1'b0}});
        end
    end

    genvar fb;
    generate
        for (fb = 0; fb < STRB_WIDTH; fb = fb + 1) begin : g_fbyte
            always @(posedge pclk) begin
                if (f_past_valid && $past(presetn)) begin
                    if ($past(f_wr0 && pstrb[fb]))
                        assert(reg0[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg0[8*fb +: 8] == $past(reg0[8*fb +: 8]));

                    if ($past(f_wr1 && pstrb[fb]))
                        assert(reg1[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg1[8*fb +: 8] == $past(reg1[8*fb +: 8]));

                    if ($past(f_wr2 && pstrb[fb]))
                        assert(reg2[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg2[8*fb +: 8] == $past(reg2[8*fb +: 8]));

                    if ($past(f_wr3 && pstrb[fb]))
                        assert(reg3[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg3[8*fb +: 8] == $past(reg3[8*fb +: 8]));
                end
            end
        end
    endgenerate

    // ---------------- Covers ----------------
    always @(posedge pclk) begin
        if (f_past_valid && presetn) begin
            cover(f_access && !pwrite && (paddr == 8'h00) && (prdata == 32'h1111_1111));
            cover(f_access && !pwrite && (paddr == 8'h04) && (prdata == 32'h2222_2222));
            cover(f_access && !pwrite && (paddr == 8'h08) && (prdata == 32'h4444_4444));
            cover(f_access && !pwrite && (paddr == 8'h0C) && (prdata == 32'h8888_8888));
            cover(f_access &&  pwrite && (paddr == 8'h04) && (pstrb == 4'b0100));
            cover(f_access &&  pwrite && f_mapped && (pstrb == 4'b0000));
            cover(f_access &&  pwrite && pslverr);
            cover(f_access && !pwrite && pslverr && (paddr == 8'h10));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
// Self-checking directed testbench for apb_regs.
// Inputs are driven after the falling edge and sampled 4 ns later, before the
// next rising edge. Every failed check is reported with $error and counted;
// every passing check is counted. The verdict is printed once before $finish.
`timescale 1ns/1ps
`default_nettype none

module apb_regs_tb;

    localparam integer AW = 8;
    localparam integer DW = 32;
    localparam integer SW = DW / 8;

    reg           pclk;
    reg           presetn;
    reg  [AW-1:0] paddr;
    reg           psel;
    reg           penable;
    reg           pwrite;
    reg  [DW-1:0] pwdata;
    reg  [SW-1:0] pstrb;
    wire [DW-1:0] prdata;
    wire          pready;
    wire          pslverr;

    apb_regs #(
        .ADDR_WIDTH (AW),
        .DATA_WIDTH (DW)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    // Clock: rising edges at 5, 15, 25 ...; falling edges at 10, 20, ...
    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    integer passed;
    integer failed;

    // Reference model of the four registers.
    reg [DW-1:0] model [0:3];

    // ------------------------------------------------------------------
    // Reference functions (written independently of the RTL)
    // ------------------------------------------------------------------
    function is_mapped_tb;
        input [AW-1:0] a;
        begin
            is_mapped_tb = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    function [DW-1:0] merge_tb;
        input [DW-1:0] old_v;
        input [DW-1:0] data;
        input [SW-1:0] strb;
        begin
            merge_tb = { (strb[3] ? data[31:24] : old_v[31:24]),
                         (strb[2] ? data[23:16] : old_v[23:16]),
                         (strb[1] ? data[15:8]  : old_v[15:8]),
                         (strb[0] ? data[7:0]   : old_v[7:0]) };
        end
    endfunction

    task model_reset;
        begin
            model[0] = {DW{1'b0}};
            model[1] = {DW{1'b0}};
            model[2] = {DW{1'b0}};
            model[3] = {DW{1'b0}};
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks
    // ------------------------------------------------------------------
    // Idle cycles: bus deselected, prdata and pslverr must be zero.
    task idle;
        input [31:0] n;
        reg   [31:0] c;
        begin
            for (c = 32'd0; c < n; c = c + 32'd1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = 1'b0;
                pstrb   = {SW{1'b0}};
                #4;
                if (pslverr === 1'b0) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("idle: pslverr=%b, expected 0 (addr 0x%h, t=%0t)", pslverr, paddr, $time);
                end
                if (prdata === {DW{1'b0}}) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("idle: prdata=0x%h, expected 0 (addr 0x%h, t=%0t)", prdata, paddr, $time);
                end
            end
        end
    endtask

    // One APB transfer: setup cycle, then access cycle. Checks quiet outputs
    // in setup, and pready / pslverr / prdata in access.
    task xfer;
        input          wr;
        input [AW-1:0] addr;
        input [DW-1:0] wdata;
        input [SW-1:0] strb;
        input          exp_err;
        input [DW-1:0] exp_rdata;
        begin
            // Setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = wr;
            paddr   = addr;
            pwdata  = wdata;
            pstrb   = wr ? strb : {SW{1'b0}};
            #4;
            if (pslverr === 1'b0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("setup: pslverr=%b, expected 0 (addr 0x%h, t=%0t)", pslverr, paddr, $time);
            end
            if (prdata === {DW{1'b0}}) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("setup: prdata=0x%h, expected 0 (addr 0x%h, t=%0t)", prdata, paddr, $time);
            end

            // Access phase
            @(negedge pclk);
            penable = 1'b1;
            #4;
            if (pready === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("access: pready=%b, expected 1 (zero wait states) (addr 0x%h, t=%0t)", pready, paddr, $time);
            end
            if (pslverr === exp_err) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("access: pslverr=%b, expected %b (write=%b addr 0x%h, t=%0t)", pslverr, exp_err, wr, paddr, $time);
            end
            if (prdata === exp_rdata) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("access: prdata=0x%h, expected 0x%h (write=%b addr 0x%h, t=%0t)", prdata, exp_rdata, wr, paddr, $time);
            end
        end
    endtask

    task do_write;
        input [AW-1:0] addr;
        input [DW-1:0] data;
        input [SW-1:0] strb;
        reg            m;
        begin
            m = is_mapped_tb(addr);
            xfer(1'b1, addr, data, strb, !m, {DW{1'b0}});
            // The write commits on the rising edge that ends the access phase.
            if (m) model[addr[3:2]] = merge_tb(model[addr[3:2]], data, strb);
        end
    endtask

    task do_read;
        input [AW-1:0] addr;
        reg            m;
        begin
            m = is_mapped_tb(addr);
            xfer(1'b0, addr, 32'hDEAD_BEEF, {SW{1'b0}}, !m,
                 m ? model[addr[3:2]] : {DW{1'b0}});
        end
    endtask

    // Reset with the bus idle (manager keeps psel low in reset).
    task do_reset;
        input [31:0] n;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = {SW{1'b0}};
            idle(n);
            presetn = 1'b1;
            model_reset;
            idle(32'd1);
        end
    endtask

    // ------------------------------------------------------------------
    // Directed sequence
    // ------------------------------------------------------------------
    reg [8:0]      aa;
    reg [7:0]      a;
    reg [4:0]      s;
    reg [DW-1:0]   d;
    reg [8*64-1:0] nonce;
    integer        got_nonce;

    initial begin
        passed    = 0;
        failed    = 0;
        nonce     = {(8*64){1'b0}};
        got_nonce = 0;

        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = {AW{1'b0}};
        pwdata  = {DW{1'b0}};
        pstrb   = {SW{1'b0}};
        model_reset;

        // Reset held for three cycles with the bus idle; outputs quiet.
        idle(32'd3);
        presetn = 1'b1;
        idle(32'd2);

        // 1. Reset values of every register, with idle gaps.
        for (a = 8'h00; a < 8'h10; a = a + 8'h04) begin
            do_read(a);
            idle(32'd1);
        end

        // 2. Full-word writes to every register, back to back, then read back
        //    back to back.
        do_write(8'h00, 32'h1234_5678, 4'hF);
        do_write(8'h04, 32'h9ABC_DEF0, 4'hF);
        do_write(8'h08, 32'hA5A5_5A5A, 4'hF);
        do_write(8'h0C, 32'hFFFF_0000, 4'hF);
        do_read(8'h00);
        do_read(8'h04);
        do_read(8'h08);
        do_read(8'h0C);
        idle(32'd3);

        // Read immediately after a write to the same register, then reads
        // separated by idle gaps of different lengths.
        do_write(8'h08, 32'h0F0F_F0F0, 4'hF);
        do_read(8'h08);
        do_read(8'h0C);
        idle(32'd1);
        do_read(8'h04);
        idle(32'd2);
        do_read(8'h00);

        // All ones then all zeros on every register.
        for (a = 8'h00; a < 8'h10; a = a + 8'h04) begin
            do_write(a, 32'hFFFF_FFFF, 4'hF);
            do_read(a);
        end
        for (a = 8'h00; a < 8'h10; a = a + 8'h04) begin
            do_write(a, 32'h0000_0000, 4'hF);
            do_read(a);
        end
        idle(32'd1);

        // 3. Every pstrb pattern (including all zero) on every register,
        //    each over a full-word background of the inverted data.
        for (a = 8'h00; a < 8'h10; a = a + 8'h04) begin
            for (s = 5'd0; s < 5'd16; s = s + 5'd1) begin
                d = {4{3'b101, s}};
                do_write(a, ~d, 4'hF);
                do_write(a, d, s[3:0]);
                do_read(a);
                if (s[1:0] == 2'b11) idle(32'd1);
            end
        end

        // 4. PSLVERR policy: give each register a distinct value, then sweep
        //    every address in the slot. Unmapped addresses (misaligned, or
        //    0x10 and above) are written and read: error, read data zero,
        //    no register changes. Mapped addresses are read back.
        do_write(8'h00, 32'hC0DE_0000, 4'hF);
        do_write(8'h04, 32'hC0DE_0004, 4'hF);
        do_write(8'h08, 32'hC0DE_0008, 4'hF);
        do_write(8'h0C, 32'hC0DE_000C, 4'hF);
        for (aa = 9'd0; aa < 9'd256; aa = aa + 9'd1) begin
            a = aa[7:0];
            if (!is_mapped_tb(a)) do_write(a, {4{a}}, 4'hF);
            do_read(a);
            if (aa[2:0] == 3'd5) idle(32'd2);
        end
        // Unmapped writes with partial and zero strobes also error.
        do_write(8'h11, 32'h1111_1111, 4'h3);
        do_write(8'h02, 32'h2222_2222, 4'h0);
        do_write(8'hFC, 32'h3333_3333, 4'h8);
        // Registers unchanged by every unmapped write.
        for (a = 8'h00; a < 8'h10; a = a + 8'h04) begin
            do_read(a);
        end
        idle(32'd2);

        // 5. Reset again: every register returns to zero, block still works.
        do_reset(32'd2);
        for (a = 8'h00; a < 8'h10; a = a + 8'h04) begin
            do_read(a);
        end
